from unittest.mock import Mock

def retry_read(read, sleep, attempts=3):
    if attempts < 1:
        raise ValueError('attempts must be positive')
    for number in range(attempts):
        try:
            return read()
        except TimeoutError:
            if number == attempts - 1:
                raise
            sleep(1)

read = Mock(side_effect=[TimeoutError('temporary'), 'ready'])
sleep = Mock()
assert retry_read(read, sleep) == 'ready'
assert read.call_count == 2
sleep.assert_called_once_with(1)
always_fails = Mock(side_effect=TimeoutError('offline'))
pauses = Mock()
try:
    retry_read(always_fails, pauses, attempts=2)
except TimeoutError:
    pass
else:
    raise AssertionError('final timeout was hidden')
assert always_fails.call_count == 2
pauses.assert_called_once_with(1)
wrong_error = Mock(side_effect=ValueError('bad request'))
try:
    retry_read(wrong_error, Mock())
except ValueError:
    pass
else:
    raise AssertionError('permanent error was hidden')
assert wrong_error.call_count == 1
print('bounded retry tests passed')
